#!/usr/bin/env python3
"""Canonical VPMOVMSKB compared with independent Python mask values."""
import hashlib,json,pathlib,random,subprocess
R=pathlib.Path(__file__).resolve().parents[1];sha=lambda p:hashlib.sha256(p.read_bytes()).hexdigest();out=R/'generated/sse/movmskb-reference';out.mkdir(parents=True,exist_ok=True);rng=random.Random(25034);requests=[];expected=[]
for mode in range(2):
 for i in range(65536):
  mask=i|(((i*40503)&65535)<<16);data=bytes((rng.randrange(128)|(((mask>>j)&1)*128)) for j in range(32));vectors=[[rng.getrandbits(64) for _ in range(4)] for _ in range(3)];vectors[1]=[int.from_bytes(data[j:j+8],'little') for j in range(0,32,8)];setting=i%16;sticky=[0,1,31,63][(i//16)%4];control=0x1f80|((setting&3)<<13)|(0x40 if setting&4 else 0)|(0x8000 if setting&8 else 0)|sticky;flags=[0,0x8d5,0x41,0x884][i%4];word=rng.getrandbits(32);requests.append(f'{mode} {control:x} {flags:x} {word:x} '+' '.join(f'{v:016x}' for row in vectors for v in row)+' 0\n');expected.append([v for row in vectors for v in row]+[word,control,flags]+vectors[2]+[mask if mode else i])
request=''.join(requests);(out/'requests.txt').write_text(request);source=R/'tests/movmskb_oracle.c';exe=out/'oracle-x86';subprocess.run(['clang','-arch','x86_64','-O2','-mno-red-zone','-Wall','-Wextra','-Werror',str(source),'-o',str(exe)],check=True);run=subprocess.run(['arch','-x86_64',str(exe)],input=request,text=True,capture_output=True,check=True,timeout=120);(out/'reference.txt').write_text(run.stdout);replies=run.stdout.splitlines();assert len(replies)==len(expected)
for i,(reply,want) in enumerate(zip(replies,expected)):assert [int(x,16) for x in reply.split()]==want,(i,reply,want)
r={'pass':True,'state':'finished','cases':len(expected),'modes':2,'source_sha256':sha(source),'verifier_sha256':sha(pathlib.Path(__file__)),'requests_sha256':sha(out/'requests.txt'),'reference_sha256':sha(out/'reference.txt'),'binary_sha256':sha(exe),'scope':'Canonical Rosetta VPMOVMSKB XMM/YMM to EAX with all65536sign patterns per16byte half, mixed low7bits, independent Python masks; full3YMM/source preservation, fullRAX zeroextension, flags/maskedMXCSR/memory. Separate native corpus; not physicalIntel/fullinitialization/gameplay proof.'};(out/'result.json').write_text(json.dumps(r,indent=2)+'\n');print('PASS: %d canonical VPMOVMSKB cases'%len(expected))
